18	function esc(v) {
19	  if (v === null || v === undefined) return "";
20	  return String(v)
21	    .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
22	    .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
23	}
24	
25	function relTime(ts) {
26	  if (!ts) return "";
27	  const s = Math.max(0, Math.round(Date.now() / 1000 - ts));
28	  if (s < 5) return "just now";
29	  if (s < 60) return s + "s ago";
30	  const m = Math.floor(s / 60);
31	  if (m < 60) return m + "m ago";
32	  const h = Math.floor(m / 60);
33	  if (h < 24) return h + "h " + (m % 60) + "m ago";
34	  return Math.floor(h / 24) + "d ago";
35	}
36	
37	function clockTime(ts) {
38	  if (!ts) return "";
39	  const d = new Date(ts * 1000);
40	  return d.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit", second: "2-digit", hour12: false });
41	}
42	
43	function fmtBytes(n) {
44	  if (n === null || n === undefined || isNaN(n)) return "–";
45	  const u = ["B", "KB", "MB", "GB", "TB"];
46	  let i = 0, v = Number(n);
47	  while (v >= 1024 && i < u.length - 1) { v /= 1024; i++; }
48	  return (i === 0 ? v : v.toFixed(v < 10 ? 1 : 0)) + " " + u[i];
49	}
50	
51	function fmtCost(c) {
52	  if (c === null || c === undefined) return "";
53	  return "$" + Number(c).toFixed(2);
54	}
55	
56	function basename(p) {
57	  if (!p) return "";
58	  const parts = String(p).replace(/\/+$/, "").split("/");
59	  return parts[parts.length - 1] || p;
60	}
61	
62	function runTitle(run) {
63	  if (run.title) return run.title;
64	  const t = (run.task || "").trim().split("\n")[0];
65	  return t.length > 70 ? t.slice(0, 67) + "…" : (t || "Untitled run");
66	}
