68	/* Fill every element with data-ts with its relative time. Cheap; runs every second. */
69	function updateRelTimes(root = document) {
70	  for (const el of $$(".rel[data-ts]", root)) {
71	    const txt = relTime(Number(el.dataset.ts));
72	    if (el.textContent !== txt) el.textContent = txt;
73	  }
