85	/* Tiny safe markdown: escape first, then `code`, **bold**, bullets, headings, fences. */
86	function miniMarkdown(text) {
87	  const lines = String(text || "").split("\n");
88	  let out = [], fence = false;
89	  for (const raw of lines) {
90	    if (/^\s*```/.test(raw)) { fence = !fence; out.push('<span class="md-fence">' + esc(raw) + "</span>"); continue; }
91	    let line = esc(raw);
92	    if (fence) { out.push('<span class="md-code">' + line + "</span>"); continue; }
93	    line = line.replace(/`([^`]+)`/g, "<code>$1</code>")
94	               .replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>");
95	    let m;
96	    if ((m = line.match(/^(\s*)[-*] (.*)$/))) line = m[1] + '<span class="md-bullet">•</span> ' + m[2];
97	    else if ((m = line.match(/^#{1,6} (.*)$/))) line = '<strong class="md-h">' + m[1] + "</strong>";
98	    out.push(line);
99	  }
100	  return out.join("\n");
101	}
