109	async function api(method, path, body) {
110	  const opts = { method, headers: {} };
111	  if (body !== undefined) { opts.headers["Content-Type"] = "application/json"; opts.body = JSON.stringify(body); }
112	  let resp;
113	  try {
114	    resp = await fetch(path, opts);
115	  } catch (e) {
116	    throw new ApiError("Cannot reach the conductor server", 0, true);
117	  }
118	  let data = null;
119	  const text = await resp.text().catch(() => "");
120	  try { data = text ? JSON.parse(text) : null; } catch (e) { data = null; }
121	  if (!resp.ok) {
122	    const msg = (data && data.error) || (text && text.length < 300 ? text : "") || ("HTTP " + resp.status);
123	    throw new ApiError(msg, resp.status, resp.status === 502 || resp.status === 503 || resp.status === 504);
124	  }
125	  return data;
126	}
