174	function boardSections(runs) {
175	  const needs = [], progress = [], done = [];
176	  for (const r of runs) {
177	    if (TERMINAL.has(r.state)) done.push(r);
178	    else if ((r.attention_score || 0) >= NEEDS_SCORE) needs.push(r);
179	    else progress.push(r);   // running/starting/testing/queued (+ anything unexpected)
180	  }
181	  done.sort((a, b) => (b.finished_at || b.updated_at || 0) - (a.finished_at || a.updated_at || 0) || b.id - a.id);
182	  return { needs, progress, done: done.slice(0, 20) };
