291	      (run.id === state.selectedId ? " selected" : "");
292	    setHTML(el, cardHTML(run, section));
293	    if (container.children[i] !== el) container.insertBefore(el, container.children[i] || null);
294	    el._seen = true;
295	  });
296	  while (container.children.length > runs.length) container.lastElementChild.remove();
297	}
