322	/* ───────────────────────── reaching you ─────────────────────────
323	   Only one thing interrupts you: a run that has just started needing you
324	   (blocked on a question, ready to merge, failed...). Nothing else notifies. */
325	
326	const notified = new Map(); // run id -> attention reason we already told you about
327	let notifyPrimed = false;   // don't fire for everything already waiting at page load
328	
329	function notifyNewlyNeeding(needs) {
330	  const fresh = [];
331	  const live = new Set();
332	  for (const r of needs) {
333	    live.add(r.id);
334	    if (notified.get(r.id) !== r.attention_reason) {
335	      notified.set(r.id, r.attention_reason);
336	      fresh.push(r);
337	    }
338	  }
339	  for (const id of [...notified.keys()]) if (!live.has(id)) notified.delete(id);
340	  if (!notifyPrimed) { notifyPrimed = true; return; }
341	  if (!fresh.length || !("Notification" in window) || Notification.permission !== "granted") return;
342	  if (document.visibilityState === "visible" && document.hasFocus()) return; // you're already looking
343	  for (const r of fresh.slice(0, 3)) {
344	    const n = new Notification("#" + r.id + " " + r.title, {
345	      body: r.attention_reason + (r.state === "waiting_input" && r.question ? "\n" + r.question : ""),
346	      tag: "conductor-run-" + r.id,
347	    });
348	    n.onclick = () => { window.focus(); location.hash = "#run-" + r.id; n.close(); };
349	  }
350	}
