633	/* Parse a unified diff into files → hunks → lines. */
634	function parseDiff(text) {
635	  const files = [];
636	  let f = null, h = null, oldN = 0, newN = 0;
637	  const lines = String(text || "").split("\n");
638	  if (lines.length && lines[lines.length - 1] === "") lines.pop();
639	  const unq = (p) => p.replace(/^"(.*)"$/, "$1");
640	  for (const line of lines) {
641	    if (line.startsWith("diff --git ")) {
642	      const m = line.match(/^diff --git (?:"?a\/)(.+?)"? (?:"?b\/)(.+?)"?$/);
643	      f = { path: m ? m[2] : line.slice(11), oldPath: m ? m[1] : null, meta: [], hunks: [], binary: false, nlines: 0 };
644	      files.push(f); h = null; continue;
645	    }
646	    if (!f) continue;
647	    if (!h) {
648	      if (line.startsWith("+++ ")) { const p = unq(line.slice(4)); if (p !== "/dev/null") f.path = p.replace(/^b\//, ""); continue; }
649	      if (line.startsWith("--- ")) { const p = unq(line.slice(4)); if (p !== "/dev/null") f.oldPath = p.replace(/^a\//, ""); continue; }
650	      if (line.startsWith("Binary files") || line.startsWith("GIT binary patch")) { f.binary = true; f.meta.push(line); continue; }
651	    }
652	    const hm = line.match(/^@@ -(\d+)(?:,\d+)? \+(\d+)(?:,\d+)? @@(.*)$/);
653	    if (hm) {
654	      h = { header: line, lines: [] }; f.hunks.push(h);
655	      oldN = Number(hm[1]); newN = Number(hm[2]); f.nlines++; continue;
656	    }
657	    if (!h) { f.meta.push(line); continue; }
658	    const c = line[0];
659	    if (c === "+") h.lines.push({ t: "add", o: "", n: newN++, s: line.slice(1) });
660	    else if (c === "-") h.lines.push({ t: "del", o: oldN++, n: "", s: line.slice(1) });
661	    else if (c === "\\") h.lines.push({ t: "meta", o: "", n: "", s: line });
662	    else h.lines.push({ t: "ctx", o: oldN++, n: newN++, s: line.slice(1) });
663	    f.nlines++;
664	  }
665	  return files;
666	}
