input.content:
const { chromium } = require("playwright");
const OUT = "/tmp/claude-0/ui-mock2/";
const BASE = "http://127.0.0.1:" + (process.env.PORT || 8765) + "/";
(async () => {
  const browser = await chromium.launch();
  const scheme = process.env.SCHEME || "light";
  const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 }, colorScheme: scheme });
  const page = await ctx.newPage();
  const errors = [];
  page.on("console", (m) => { if (m.type() === "error" || m.type() === "warning") errors.push(m.type() + ": " + m.text()); });
  page.on("pageerror", (e) => errors.push("pageerror: " + e.message));
  const sfx = "-" + scheme + ".png";

  await page.goto(BASE);
  await page.waitForSelector("#n3-cards .n3-card");
  await page.waitForTimeout(400);
  // expand first group
  await page.click("#groups .group:first-child .g-head");
  await page.waitForSelector("#groups .group:first-child .g-body .card");
  await page.waitForTimeout(300);
  await page.screenshot({ path: OUT + "board" + sfx });

  // show more on needs
  const before = await page.$$eval("#cards-needs .card", (a) => a.length);
  const moreVisible = await page.isVisible('[data-more="needs"]');
  // done section expand
  await page.click("#sec-done > summary");
  await page.waitForSelector("#cards-done .card");
  const doneN = await page.$$eval("#cards-done .card", (a) => a.length);
  await page.evaluate(() => document.querySelector('[data-more="done"]').scrollIntoView());
  await page.click('[data-more="done"]');
  await page.waitForFunction(() => document.querySelectorAll("#cards-done .card").length > 50);
  const doneN2 = await page.$$eval("#cards-done .card", (a) => a.length);
  console.log("needs cards", before, "more visible", moreVisible, "done", doneN, "->", doneN2);

  // search
  await page.fill("#search", "Dependency");
  await page.waitForTimeout(900);
  const nAfterSearch = await page.$$eval("#cards-needs .card", (a) => a.length);
  console.log("needs after search", nAfterSearch, await page.textContent("#filter-note"));
  await page.screenshot({ path: OUT + "search" + sfx });
  await page.fill("#search", "");
  await page.waitForTimeout(900);
  await page.selectOption("#repo-filter", "/home/lead/acme/infra");
  await page.waitForTimeout(600);
  console.log("repo filter needs", await page.$$eval("#cards-needs .card", (a) => a.length));
  await page.selectOption("#repo-filter", "");
  await page.waitForTimeout(600);

  // bulk op
  page.once("dialog", (d) => { console.log("confirm:", d.message().replace(/\n/g, " | ")); d.accept(); });
  await page.click("#groups .group:first-child [data-gop=accept_ready]");
  await page.waitForSelector(".toast");
  await page.waitForTimeout(300);
  await page.screenshot({ path: OUT + "bulk-toast" + sfx });

  // review tab of policy run via next3 "Review"
  await page.click('#n3-cards [data-n3="review"]');
  await page.waitForSelector("#rv-policy .pol-item");
  await page.click("#rv-policy details.eff-pol > summary");
  await page.waitForSelector("#rv-policy .rules");
  await page.waitForTimeout(2500);  // a poll cycle: make sure details stays open
  console.log("eff policy still open:", await page.$eval("#rv-policy details.eff-pol", (d) => d.open));
  await page.evaluate(() => document.querySelector("#rv-policy").scrollIntoView());
  await page.screenshot({ path: OUT + "review-policy" + sfx });

  // override dialog
  await page.click('#d-actions [data-action="accept_override"]');
