.sc-acts .btn + .btn { margin-left: 4px; }
.sc-paused td { opacity: .6; }
.sc-paused td:nth-last-child(-n+2) { opacity: 1; }
.switch { position: relative; display: inline-block; width: 30px; height: 17px; cursor: pointer; }
.switch input { opacity: 0; width: 0; height: 0; position: absolute; }
.switch .slider { position: absolute; inset: 0; border-radius: 999px; background: var(--border-strong); transition: background .15s; }
.switch .slider::before { content: ""; position: absolute; width: 13px; height: 13px; left: 2px; top: 2px; border-radius: 50%; background: #fff; transition: transform .15s; }
