const { chromium } = require("playwright");
const OUT = "/tmp/claude-0/p2ui-shots/", B = "http://127.0.0.1:7822/";
(async () => {
  const br = await chromium.launch();
  const page = await (await br.newContext({ viewport: { width: 1440, height: 900 } })).newPage();
  const errors = [];
  page.on("console", (m) => { if (m.type() === "error") errors.push(m.text()); });
  page.on("pageerror", (e) => errors.push("pageerror: " + e.message));
  await page.goto(B + "#run-4");
  await page.waitForSelector("#n3-cards .n3-card"); await page.waitForTimeout(1500);
  const tones = await page.$$eval("#cards-needs .card", (cs) => cs.map((c) => c.querySelector(".c-title").textContent + " | " +
    ((c.querySelector(".c-reason") || {}).className || "") + " | chip=" + !!c.querySelector(".chip-policy") + " | " + ((c.querySelector(".wf-step") || {}).textContent || "")));
  console.log(tones.join("\n"));
  console.log("n3:", await page.$$eval(".n3-card", (cs) => cs.map((c) => c.className + " / " + c.querySelector("[data-n3]").textContent)));
  await page.screenshot({ path: OUT + "board.png" });

  // workflow run at gate
  await page.click('#cards-needs .card[data-id="1"]');
  await page.waitForSelector("#q-approve:not([hidden])"); await page.waitForTimeout(500);
  console.log("q-label:", await page.textContent("#q-label"), "| textarea:", JSON.stringify(await page.inputValue("#q-answer")));
  console.log("tracker:", await page.$$eval(".wf-track li", (ls) => ls.map((l) => l.className + ":" + l.textContent)));
  await page.screenshot({ path: OUT + "gate.png" });
  await page.click('#d-tabs [data-tab="activity"]'); await page.waitForTimeout(300);
  console.log("wf events:", await page.$$eval(".ev-wfstep", (e) => e.map((x) => x.textContent)));
  await page.screenshot({ path: OUT + "gate-activity.png" });

  // new run dialog with workflow
  await page.keyboard.press("Escape");
  await page.click("#new-run-btn");
  await page.fill("#f-repo", "/tmp/claude-0/p2ui/repo"); await page.dispatchEvent("#f-repo", "change");
  await page.waitForFunction(() => document.querySelectorAll("#f-workflow option").length > 1);
  await page.selectOption("#f-workflow", "feature");
  await page.fill("#f-task", "Add a reverse_words() helper to textkit with tests");
  await page.waitForTimeout(300);
  await page.screenshot({ path: OUT + "new-run-workflow.png" });
  await page.click("#f-cancel");

  // schedules
  await page.click("#sched-btn");
  await page.waitForSelector("#sc-body .sc-table");
  await page.click("#sc-new");
  await page.fill("#sc-name", "Weekly dependency check");
  await page.waitForFunction(() => document.querySelectorAll("#sc-workflow option").length > 1);
  await page.selectOption("#sc-workflow", "dependency-bump");
  await page.fill("#sc-task", "Bump outdated dependencies");
  await page.fill("#sc-cron", "61 3 * * 1-5");
  await page.click("#sc-submit");
  await page.waitForFunction(() => document.querySelector("#sc-err").textContent.length > 0);
  console.log("sched err:", await page.textContent("#sc-err"));
  await page.screenshot({ path: OUT + "schedules.png" });
  await page.click("#sc-kind-change"); await page.waitForTimeout(100);
  await page.screenshot({ path: OUT + "schedules-onchange.png" });
  await page.click("#sc-kind-cron");
  await page.fill("#sc-cron", "0 6 * * 1");
  await page.click("#sc-submit");
  await page.waitForFunction(() => document.querySelector("#sc-form").hidden);
  // pause via toggle, run now
  await page.click('#sc-body tr[data-sc="2"] .switch');
  await page.waitForTimeout(800);
  page.once("dialog", (d) => d.accept());
  await page.click('#sc-body tr[data-sc="3"] [data-sc-op="delete"]');
  await page.waitForTimeout(800);
  await page.click('#sc-body tr[data-sc="1"] [data-sc-op="run_now"]');
  await page.waitForTimeout(1500);
  console.log("rows:", await page.$$eval("#sc-body tr[data-sc]", (rs) => rs.map((r) => r.dataset.sc + (r.classList.contains("sc-paused") ? " paused" : " on"))));
  await page.screenshot({ path: OUT + "schedules-list.png" });
  await page.click("#sc-close");

  // approve the gate
  await page.click('#cards-needs .card[data-id="1"]');
  await page.waitForSelector("#q-approve:not([hidden])");
  await page.click("#q-approve");
  await page.waitForTimeout(1500);
  console.log("after approve state:", await page.$eval("#d-head .pill", (p) => p.textContent), await page.$$eval(".wf-track li", (ls) => ls.map((l) => l.className)));
  console.log("errors:", JSON.stringify(errors));
  await br.close();
})().catch((e) => { console.error(e); process.exit(1); });
EOF
